// Input: current column letter (e.g., 'A', 'Z', 'AA', 'AZ', ...)

const currentLetter = $('Get Week Index').first().json.col_1;

function incrementExcelColumn(col) {
  let carry = 1;
  let result = "";

  for (let i = col.length - 1; i >= 0; i--) {
    let charCode = col.charCodeAt(i) - 65; // Convert 'A'..'Z' to 0..25
    charCode += carry;

    if (charCode === 26) {
      charCode = 0;
      carry = 1;
    } else {
      carry = 0;
    }

    result = String.fromCharCode(65 + charCode) + result;
  }

  if (carry === 1) {
    result = "A" + result;
  }

  return result;
}

// Calculate nextLetter (1 step ahead)
let nextLetter = incrementExcelColumn(currentLetter);

// Calculate nextFourthLetter (4 steps ahead)
let current = currentLetter;
for (let i = 0; i < 4; i++) {
  current = incrementExcelColumn(current);
}
let nextFourthLetter = current;

return {
  nextLetter,
  nextFourthLetter
};

// Input: current column letter (e.g., 'A', 'Z', 'AA', 'AZ', 'ZZ', ...)

const currentLetter = $('Get Week Index').first().json.col_1;

// Convert Excel column letter (e.g., 'AB') to a number (e.g., 28)
function columnLetterToNumber(col) {
  let num = 0;
  for (let i = 0; i < col.length; i++) {
    num = num * 26 + (col.charCodeAt(i) - 64); // 'A' = 65
  }
  return num;
}

// Convert number (e.g., 28) to Excel column letter (e.g., 'AB')
function numberToColumnLetter(num) {
  let col = '';
  while (num > 0) {
    let rem = (num - 1) % 26;
    col = String.fromCharCode(65 + rem) + col;
    num = Math.floor((num - 1) / 26);
  }
  return col;
}

const currentNumber = columnLetterToNumber(currentLetter);
const nextNumber = currentNumber + 3;
const nextLetter = numberToColumnLetter(nextNumber);

return {nextLetter};

