// Get all campaign reports from previous node
const reports = $('Get Campaign Report (TIF)').all();

if (reports.length === 0) {
  return {
    error: 'No campaign reports found',
    metrics: {
      avgOpenRate: '0%',
      avgClickRate: '0%',
      avgUnsubscribeRate: '0%'
    }
  };
}

// Initialize variables for calculation
let totalOpenRate = 0;
let totalClickRate = 0;
let totalUnsubscribeRate = 0;
let validCampaigns = 0;

// For weighted averages (optional)
let totalEmailsSent = 0;
let totalOpens = 0;
let totalClicks = 0;
let totalUnsubscribed = 0;

// Process each campaign report
reports.forEach(item => {
  const report = item.json;

  validCampaigns++;

  // Get the rates (MailChimp returns them as decimals)
  const openRate = report.opens?.open_rate || 0;
  const clickRate = report.clicks?.click_rate || 0;

  // Calculate unsubscribe rate
  const unsubscribed = report.unsubscribed || 0;
  const unsubscribeRate = unsubscribed / report.emails_sent;

  // Sum rates for simple average
  totalOpenRate += openRate;
  totalClickRate += clickRate;
  totalUnsubscribeRate += unsubscribeRate;

  // Collect totals for weighted average (optional)
  totalEmailsSent += report.emails_sent;
  totalOpens += report.opens?.opens_total || 0;
  totalClicks += report.clicks?.clicks_total || 0;
  totalUnsubscribed += unsubscribed;
});

// Calculate simple averages (average of averages)
const avgOpenRate = validCampaigns > 0 ? (totalOpenRate / validCampaigns * 100) : 0;
const avgClickRate = validCampaigns > 0 ? (totalClickRate / validCampaigns * 100) : 0;
const avgUnsubscribeRate = validCampaigns > 0 ? (totalUnsubscribeRate / validCampaigns * 100) : 0;

// Calculate weighted averages (based on total emails)
const weightedOpenRate = totalEmailsSent > 0 ? (totalOpens / totalEmailsSent * 100) : 0;
const weightedClickRate = totalEmailsSent > 0 ? (totalClicks / totalEmailsSent * 100) : 0;
const weightedUnsubscribeRate = totalEmailsSent > 0 ? (totalUnsubscribed / totalEmailsSent * 100) : 0;

// Return both simple and weighted averages
return {
  summary: {
    campaignsAnalyzed: validCampaigns,
    totalEmailsSent: totalEmailsSent,
  },

  // Simple averages (average of percentages)
  simpleAverages: {
    avgOpenRate: avgOpenRate.toFixed(2) + '%',
    avgClickRate: avgClickRate.toFixed(2) + '%',
    avgUnsubscribeRate: avgUnsubscribeRate.toFixed(3) + '%'
  },

  // Weighted averages (total opens/total sent, etc.)
  weightedAverages: {
    openRate: weightedOpenRate.toFixed(2) + '%',
    clickRate: weightedClickRate.toFixed(2) + '%',
    unsubscribeRate: weightedUnsubscribeRate.toFixed(3) + '%'
  }
};

