const insights = $input.first().json.data;
let totalFollows = 0;
let totalUnfollows = 0;

// Find the object with the follows data
const followsData = insights.find(metric => metric.name === 'page_daily_follows_unique');

// If follows data exists, loop through its daily values and sum them up
if (followsData && followsData.values) {
  for (const dailyValue of followsData.values) {
    totalFollows += dailyValue.value;
  }
}

// Find the object with the unfollows data
const unfollowsData = insights.find(metric => metric.name === 'page_daily_unfollows_unique');

// If unfollows data exists, loop through its daily values and sum them up
if (unfollowsData && unfollowsData.values) {
  for (const dailyValue of unfollowsData.values) {
    totalUnfollows += dailyValue.value;
  }
}

// Calculate the final net growth
const netGrowth = totalFollows - totalUnfollows;

// Return a single object with the final numbers
return {totalFollows, totalUnfollows, FB_net_follower_growth: netGrowth};

